description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "安金俊", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：安金俊。", "biography": null, "status": "draft", "id": "ed86f959-3dec-540b-b852-5e50fe5a19a5"}, {"name": "申信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：申信。", "biography": null, "status": "draft", "id": "6deb135d-b49b-5735-b03a-e34de6f4ad4e"}, {"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "石君和", "aliases": ["石和"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：石君和。", "biography": null, "status": "draft", "id": "6a929f8d-8014-5859-bf07-c1d972e6b4ca"}, {"name": "李克修", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李克修。", "biography": null, "status": "draft", "id": "5fa53ae8-ca62-51b5-ab38-b065ef6bf2d8"}, {"name": "李克恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：李克恭。", "biography": null, "status": "draft", "id": "e3d4fb3f-6943-5ead-a384-1e9600a03c81"}, {"name": "张筠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：张筠。", "biography": null, "status": "draft", "id": "bf64af0b-0098-59b2-a778-9ac82b9245d0"}, {"name": "张绍光", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：张绍光。", "biography": null, "status": "draft", "id": "1aba28