INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "马敬言乘虚据润州", "start_year": 890, "end_year": 890, "time_original": "890年二月后条；具体日未载", "dynasty": "唐", "description": "杨行密遣马敬言率兵乘虚袭据润州。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "100c94fd-4c7d-5f4a-a25e-9be9e6ff1326"}, {"title": "李友屯青城拟攻常州", "start_year": 890, "end_year": 890, "time_original": "890年二月后条；具体日未载", "dynasty": "唐", "description": "李友率兵屯青城，准备攻常州。《通鉴》称李友为合肥人。", "phases": [], "location_name": "青城、常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "94dda773-238a-5f56-9cac-9e89b2d1ca32"}, {"title": "安仁义刘威田頵败刘锋于武进", "start_year": 890, "end_year": 890, "time_original": "890年二月后条；具体日未载", "dynasty": "唐", "description": "安仁义、刘威、田頵在武进击败刘锋；马敬言、安仁义、刘威屯润州。《通鉴》称刘威为慎县人。", "phases": [], "location_name": "武进、润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c21e1fa6-4abf-5d04-a3a1-78ca3f08b93c"}, {"title": "李克用攻云州东城，李匡威来援", "start_year": 890, "end_year": 890, "time_original": "890年二月丙子条前后；具体日未逐项记载", "dynasty": "唐", "description": "李克用率兵攻云州防御使赫连铎，攻取东城；赫连铎向李匡威求救，李匡威率兵来援。", "phases": [], "location_name": "云州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8c3dc7f2-8da3-54ed-b299-567d576bfae9"}, {"title": "安金俊中流矢死，申信降赫连铎", "start_year": 890, "end_year": 890, "time_original": "890年二月丙子", "dynasty": "唐", "description": "邢洺团练使安金俊中流矢死亡，河东万胜军使申信叛降赫连铎；幽州军抵达后，李克用撤军。", "phases": [], "location_name": "云州战场", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "60058331-4a9c-5d20-80ef-a88a834708ee"}, {"title": "李克用遣石和援时溥", "start_year": 890, "end_year": 890, "time_original": "890年二月后条；具体日未载", "dynasty": "唐", "description": "时溥向河东求救，李克用遣其将石和率五百骑前往援助。", "phases": [], "location_name": "徐州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bbe929b4-d482-539d-84cb-20c5a6f446ac"}, {"title": "李克用因供具责打李克修", "start_year": 890, "end_year": 890, "time_original": "890年三月前；具体日未载", "dynasty": "唐", "description": "李克用巡视潞州，因供具不厚而怒，辱骂并笞打昭义节度使李克修。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3bcb87d0-435e-5358-ad62-1c4b5432b1df"}, {"title": "李克修卒，李克用表李克恭留后", "start_year": 890, "end_year": 890, "time_original": "890年三月", "dynasty": "唐", "description": "《通鉴》记李克修惭愤成疾，三月去世；李克用上表请其弟、决胜军使李克恭为昭义留后。", "phases": [], "location_name": "潞州、昭义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a94c50eb-ac7f-5a11-9de7-c1417ea99968"}, {"title": "宣歙赐宁国军号，杨行密任节度使", "start_year": 890, "end_year": 890, "time_original": "890年三月后条；具体日未载", "dynasty": "唐", "description": "朝廷赐宣歙军号宁国，以杨行密为节度使。", "phases": [], "location_name": "宣歙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e0a9e268-7b73-521e-b276-97d7d5052fec"}, {"title": "张筠逐张绍光附时溥，朱全忠来讨", "start_year": 890, "end_year": 890, "time_original": "890年四月", "dynasty": "唐", "description": "宿州将张筠驱逐刺史张绍光，归附时溥，朱全忠率诸军讨伐。", "phases": [], "location_name": "宿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "472d2f79-2c16-581d-951f-4b347f906975"}, {"title": "朱友裕击时溥军擒石君和", "start_year": 890, "end_year": 890, "time_original": "890年四月；具体日未载", "dynasty": "唐", "description": "时溥遣兵侵掠砀山，朱全忠遣牙内都指挥使朱友裕出击，《通鉴》记杀三千余人，俘获石君和。", "phases": [], "location_name": "砀山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fd6e4770-1452-598c-b2c6-e78575804b8e"}, {"title": "任从海援邛州败后欲降，被陈敬瑄杀", "start_year": 890, "end_year": 890, "time_original": "890年四月乙丑", "dynasty": "唐", "description": "陈敬瑄遣蜀州刺史任从海率兵救邛州，任从海战败后欲以蜀州降王建，被陈敬瑄杀死；陈敬瑄以徐公鉥代为蜀州刺史。", "phases": [], "location_name": "邛州、蜀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3e4b4e5b-9a31-5b7b-818f-65040fa20d20"}, {"title": "朱实以嘉州降王建", "start_year": 890, "end_year": 890, "time_original": "890年四月丙寅", "dynasty": "唐", "description": "嘉州刺史朱实举州投降王建。", "phases": [], "location_name": "嘉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0dbd747b-cbc1-5b3b-9f9f-5232cd7296c6"}, {"title": "文武坚执谢承恩降王建", "start_year": 890, "end_year": 890, "time_original": "890年四月丙子", "dynasty": "唐", "description": "僰道土豪文武坚拘执戎州刺史谢承恩，投降王建。", "phases": [], "location_name": "戎州、僰道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b21f38d2-d52c-54dd-a34d-f038a595b7ef"}, {"title": "赫连铎李匡威朱全忠奏请讨李克用", "start_year": 890, "end_year": 890, "time_original": "890年四月后条；具体日未载", "dynasty": "唐", "description": "赫连铎、李匡威上表请求讨李克用。朱全忠亦上言称李克用终为国患，请率汴、滑、孟三军与河北三镇共讨，并请求朝廷命大臣为统帅。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c859f82f-f2a9-5f73-baed-68625278331a"}]'::jsonb)
